const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu?.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav?.classList.remove('open');menu?.setAttribute('aria-expanded','false')}});
const search=document.querySelector('#article-search'),cat=document.querySelector('#category');function filter(){let n=0;document.querySelectorAll('.article-card').forEach(el=>{const show=el.dataset.search.includes(search.value.trim().toLowerCase())&&(!cat.value||cat.value===el.dataset.category);el.hidden=!show;if(show)n++});document.querySelector('#result-count').textContent=n+' insights';document.querySelector('#no-results').hidden=n!==0;}search?.addEventListener('input',filter);cat?.addEventListener('change',filter);
document.querySelector('#enquiry')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const text='Hello Gravita, I would like to discuss a project.\n\n'+['name','company','phone','location','service','stage','brief'].map(k=>k[0].toUpperCase()+k.slice(1)+': '+data.get(k)).join('\n');const result=document.querySelector('#enquiry-result');result.replaceChildren();result.className='toast';result.hidden=false;const p=document.createElement('p');p.textContent='Your enquiry is ready. Open WhatsApp to review and send it to Gravita.';const a=document.createElement('a');a.href='https://wa.me/919626654485?text='+encodeURIComponent(text);a.target='_blank';a.rel='noopener';a.className='button';a.textContent='Open WhatsApp and review ↗';result.append(p,a);a.focus();});
